//! Cache storage implementation.
//!
//! All writes use atomic write-to-temp-then-rename to prevent corruption
//! when multiple processes access the cache concurrently.

use anyhow::{Context, Result};
use sha2::{Digest, Sha256};
use std::fs;
use std::io::ErrorKind;
use std::path::{Path, PathBuf};

use super::entry::CacheEntry;

/// Write data atomically by writing to a temporary file then renaming.
///
/// This prevents readers from ever seeing partially-written content.
/// The rename is atomic on the same filesystem (POSIX guarantee).
fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let parent = path
        .parent()
        .with_context(|| format!("Cache path has no parent: {:?}", path))?;
    fs::create_dir_all(parent)?;

    let mut rand_bytes = [0u8; 8];
    getrandom::fill(&mut rand_bytes)
        .map_err(|e| anyhow::anyhow!("Failed to get random bytes: {}", e))?;
    let suffix = hex::encode(rand_bytes);

    let temp_path = parent.join(format!(
        ".{}.{}.tmp",
        path.file_name().unwrap_or_default().to_string_lossy(),
        suffix
    ));

    // Write to temp file, then atomically move into place.
    if let Err(e) = fs::write(&temp_path, content) {
        let _ = fs::remove_file(&temp_path);
        return Err(e).with_context(|| format!("Failed to write temp cache file {:?}", temp_path));
    }

    if let Err(e) = fs::rename(&temp_path, path) {
        let _ = fs::remove_file(&temp_path);
        return Err(e)
            .with_context(|| format!("Failed to rename cache file {:?} -> {:?}", temp_path, path));
    }

    Ok(())
}

/// Storage for cached templates.
pub struct CacheStore {
    /// Root directory for cache.
    root: PathBuf,
}

impl CacheStore {
    /// Create a new cache store.
    pub fn new(root: impl Into<PathBuf>) -> Self {
        Self { root: root.into() }
    }

    /// Get the cache root directory.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Ensure the cache directory exists.
    fn ensure_dir(&self) -> Result<()> {
        fs::create_dir_all(&self.root)
            .with_context(|| format!("Failed to create cache directory {:?}", self.root))
    }

    /// Get the path for storing an entry's content.
    pub fn content_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        let key = format!("{}:{}", source_id, template_name);
        let hash = Sha256::digest(key.as_bytes());
        let hash_str = hex::encode(&hash[..16]);
        self.root.join(hash_str)
    }

    /// Get the metadata file path for an entry.
    fn metadata_path(&self, source_id: &str, template_name: &str) -> PathBuf {
        self.content_path(source_id, template_name)
            .with_extension("meta.json")
    }

    /// Atomically write content for a cache entry.
    ///
    /// This is safe to call concurrently from multiple processes.
    pub fn write_content(&self, source_id: &str, template_name: &str, content: &str) -> Result<()> {
        self.ensure_dir()?;
        let content_path = self.content_path(source_id, template_name);
        atomic_write(&content_path, content.as_bytes())
    }

    /// Store content and return a cache entry.
    pub fn store(
        &self,
        source_id: &str,
        template_name: &str,
        content: &str,
        ttl_seconds: u64,
    ) -> Result<CacheEntry> {
        self.ensure_dir()?;

        let content_path = self.content_path(source_id, template_name);
        atomic_write(&content_path, content.as_bytes())?;

        let entry = CacheEntry::new(source_id, template_name, &content_path, ttl_seconds)
            .with_size(content.len() as u64);

        self.save_metadata(&entry)?;

        Ok(entry)
    }

    /// Load a cached entry's metadata.
    ///
    /// Returns `None` if the entry does not exist or if the metadata is
    /// unreadable (e.g., replaced mid-read by a concurrent writer that
    /// hasn't finished the rename yet).
    pub fn load(&self, source_id: &str, template_name: &str) -> Result<Option<CacheEntry>> {
        let meta_path = self.metadata_path(source_id, template_name);

        match fs::read_to_string(&meta_path) {
            Ok(json) => match serde_json::from_str::<CacheEntry>(&json) {
                Ok(entry) => Ok(Some(entry)),
                Err(_) => Ok(None), // Corrupted metadata; treat as cache miss
            },
            Err(e) if e.kind() == ErrorKind::NotFound => Ok(None),
            Err(e) => {
                Err(e).with_context(|| format!("Failed to read cache metadata {:?}", meta_path))
            }
        }
    }

    /// Read the cached content.
    pub fn read_content(&self, entry: &CacheEntry) -> Result<String> {
        fs::read_to_string(&entry.content_path).with_context(|| {
            format!(
                "Failed to read cached content from {:?}",
                entry.content_path
            )
        })
    }

    /// Save entry metadata atomically.
    fn save_metadata(&self, entry: &CacheEntry) -> Result<()> {
        let meta_path = self.metadata_path(&entry.source_id, &entry.template_name);
        let json = serde_json::to_string_pretty(entry)?;
        atomic_write(&meta_path, json.as_bytes())
    }

    /// Update an entry's metadata (e.g., after revalidation).
    pub fn update(&self, entry: &CacheEntry) -> Result<()> {
        self.save_metadata(entry)
    }

    /// Remove a cached entry.
    pub fn remove(&self, source_id: &str, template_name: &str) -> Result<bool> {
        let content_path = self.content_path(source_id, template_name);
        let meta_path = self.metadata_path(source_id, template_name);

        let mut removed = false;

        match fs::remove_file(&content_path) {
            Ok(()) => removed = true,
            Err(e) if e.kind() == ErrorKind::NotFound => {}
            Err(e) => {
                return Err(e).with_context(|| format!("Failed to remove {:?}", content_path))
            }
        }

        match fs::remove_file(&meta_path) {
            Ok(()) => removed = true,
            Err(e) if e.kind() == ErrorKind::NotFound => {}
            Err(e) => return Err(e).with_context(|| format!("Failed to remove {:?}", meta_path)),
        }

        Ok(removed)
    }

    /// List all cached entries.
    pub fn list(&self) -> Result<Vec<CacheEntry>> {
        self.ensure_dir()?;

        let mut entries = Vec::new();

        for entry in fs::read_dir(&self.root)? {
            let entry = entry?;
            let path = entry.path();

            if path.extension().is_some_and(|e| e == "json") {
                if let Ok(json) = fs::read_to_string(&path) {
                    if let Ok(cache_entry) = serde_json::from_str::<CacheEntry>(&json) {
                        entries.push(cache_entry);
                    }
                }
            }
        }

        entries.sort_by(|a, b| b.metadata.cached_at.cmp(&a.metadata.cached_at));
        Ok(entries)
    }

    /// Clear all cached entries.
    pub fn clear(&self) -> Result<usize> {
        let entries = self.list()?;
        let count = entries.len();

        for entry in entries {
            let _ = self.remove(&entry.source_id, &entry.template_name);
        }

        Ok(count)
    }

    /// Get total cache size in bytes.
    pub fn total_size(&self) -> Result<u64> {
        let entries = self.list()?;
        Ok(entries.iter().map(|e| e.metadata.size_bytes).sum())
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tempfile::TempDir;

    #[test]
    fn cache_store_creation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        assert_eq!(store.root(), temp.path());
    }

    #[test]
    fn store_and_load() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "template content", 3600)
            .unwrap();

        assert_eq!(entry.source_id, "http:test");
        assert_eq!(entry.template_name, "template1");

        let loaded = store.load("http:test", "template1").unwrap().unwrap();
        assert_eq!(loaded.source_id, entry.source_id);
        assert_eq!(loaded.template_name, entry.template_name);
    }

    #[test]
    fn read_content() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let entry = store
            .store("http:test", "template1", "hello world", 3600)
            .unwrap();

        let content = store.read_content(&entry).unwrap();
        assert_eq!(content, "hello world");
    }

    #[test]
    fn load_nonexistent_returns_none() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let result = store.load("http:test", "nonexistent").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn remove_entry() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        let removed = store.remove("http:test", "template1").unwrap();
        assert!(removed);

        let loaded = store.load("http:test", "template1").unwrap();
        assert!(loaded.is_none());
    }

    #[test]
    fn remove_nonexistent_returns_false() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let removed = store.remove("http:test", "nonexistent").unwrap();
        assert!(!removed);
    }

    #[test]
    fn list_entries() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 2);
    }

    #[test]
    fn clear_cache() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store
            .store("http:test", "template1", "content1", 3600)
            .unwrap();
        store
            .store("http:test", "template2", "content2", 3600)
            .unwrap();

        let cleared = store.clear().unwrap();
        assert_eq!(cleared, 2);

        let entries = store.list().unwrap();
        assert!(entries.is_empty());
    }

    #[test]
    fn total_size_calculation() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.store("http:test", "t1", "12345", 3600).unwrap(); // 5 bytes
        store.store("http:test", "t2", "1234567890", 3600).unwrap(); // 10 bytes

        let total = store.total_size().unwrap();
        assert_eq!(total, 15);
    }

    #[test]
    fn content_path_is_deterministic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template");
        let path2 = store.content_path("http:test", "template");

        assert_eq!(path1, path2);
    }

    #[test]
    fn different_entries_have_different_paths() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        let path1 = store.content_path("http:test", "template1");
        let path2 = store.content_path("http:test", "template2");

        assert_ne!(path1, path2);
    }

    #[test]
    fn atomic_write_produces_valid_content() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test_file");

        atomic_write(&path, b"hello atomic world").unwrap();

        let content = fs::read_to_string(&path).unwrap();
        assert_eq!(content, "hello atomic world");
    }

    #[test]
    fn atomic_write_no_leftover_temp_files() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test_file");

        atomic_write(&path, b"content").unwrap();

        let files: Vec<_> = fs::read_dir(temp.path())
            .unwrap()
            .filter_map(|e| e.ok())
            .collect();

        // Only the final file should remain, no .tmp files
        assert_eq!(files.len(), 1);
        assert_eq!(files[0].file_name(), "test_file");
    }

    #[test]
    fn atomic_write_overwrites_existing() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test_file");

        atomic_write(&path, b"first").unwrap();
        atomic_write(&path, b"second").unwrap();

        let content = fs::read_to_string(&path).unwrap();
        assert_eq!(content, "second");
    }

    #[test]
    fn concurrent_stores_produce_valid_entries() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());

        let mut handles = Vec::new();

        // Spawn multiple threads writing to different keys concurrently
        for i in 0..10 {
            let root = Arc::clone(&root);
            let handle = thread::spawn(move || {
                let store = CacheStore::new(root.as_ref());
                let name = format!("template_{}", i);
                let content = format!("content for template {}", i);
                store.store("http:test", &name, &content, 3600).unwrap();
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // All entries should be readable and valid
        let store = CacheStore::new(root.as_ref());
        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 10);

        for i in 0..10 {
            let name = format!("template_{}", i);
            let expected = format!("content for template {}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected);
        }
    }

    #[test]
    fn concurrent_writes_to_same_key_no_corruption() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());
        let barrier = Arc::new(Barrier::new(10));

        let mut handles = Vec::new();

        // Spawn multiple threads all writing to the SAME key simultaneously
        for i in 0..10 {
            let root = Arc::clone(&root);
            let barrier = Arc::clone(&barrier);
            let handle = thread::spawn(move || {
                let store = CacheStore::new(root.as_ref());
                let content = format!("content from thread {}", i);
                // Synchronize all threads to maximize contention
                barrier.wait();
                store.store("http:test", "shared", &content, 3600).unwrap();
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // The entry should be valid (one of the writers wins, but never corrupted)
        let store = CacheStore::new(root.as_ref());
        let entry = store.load("http:test", "shared").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        // Content should be from one of the threads, not a garbled mix
        assert!(content.starts_with("content from thread "));
    }

    #[test]
    fn load_returns_none_for_corrupted_metadata() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        // Write valid entry first to get the path
        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        // Corrupt the metadata file
        let meta_path = store
            .content_path("http:test", "template1")
            .with_extension("meta.json");
        fs::write(&meta_path, "not valid json {{{").unwrap();

        // Should return None instead of an error
        let result = store.load("http:test", "template1").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn write_content_is_atomic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.write_content("http:test", "tpl", "hello").unwrap();

        let path = store.content_path("http:test", "tpl");
        let content = fs::read_to_string(&path).unwrap();
        assert_eq!(content, "hello");
    }
}

