    #[test]
    fn concurrent_stores_produce_valid_entries() {
        use std::sync::Arc;
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());

        let mut handles = Vec::new();

        // Spawn multiple threads writing to different keys concurrently
        for i in 0..10 {
            let root = Arc::clone(&root);
            let handle = thread::spawn(move || {
                let store = CacheStore::new(root.as_ref());
                let name = format!("template_{}", i);
                let content = format!("content for template {}", i);
                store.store("http:test", &name, &content, 3600).unwrap();
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // All entries should be readable and valid
        let store = CacheStore::new(root.as_ref());
        let entries = store.list().unwrap();
        assert_eq!(entries.len(), 10);

        for i in 0..10 {
            let name = format!("template_{}", i);
            let expected = format!("content for template {}", i);
            let entry = store.load("http:test", &name).unwrap().unwrap();
            let content = store.read_content(&entry).unwrap();
            assert_eq!(content, expected);
        }
    }

    #[test]
    fn concurrent_writes_to_same_key_no_corruption() {
        use std::sync::{Arc, Barrier};
        use std::thread;

        let temp = TempDir::new().unwrap();
        let root = Arc::new(temp.path().to_path_buf());
        let barrier = Arc::new(Barrier::new(10));

        let mut handles = Vec::new();

        // Spawn multiple threads all writing to the SAME key simultaneously
        for i in 0..10 {
            let root = Arc::clone(&root);
            let barrier = Arc::clone(&barrier);
            let handle = thread::spawn(move || {
                let store = CacheStore::new(root.as_ref());
                let content = format!("content from thread {}", i);
                // Synchronize all threads to maximize contention
                barrier.wait();
                store.store("http:test", "shared", &content, 3600).unwrap();
            });
            handles.push(handle);
        }

        for handle in handles {
            handle.join().unwrap();
        }

        // The entry should be valid (one of the writers wins, but never corrupted)
        let store = CacheStore::new(root.as_ref());
        let entry = store.load("http:test", "shared").unwrap().unwrap();
        let content = store.read_content(&entry).unwrap();

        // Content should be from one of the threads, not a garbled mix
        assert!(content.starts_with("content from thread "));
    }

