    fn load_returns_none_for_corrupted_metadata() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        // Write valid entry first to get the path
        store
            .store("http:test", "template1", "content", 3600)
            .unwrap();

        // Corrupt the metadata file
        let meta_path = store
            .content_path("http:test", "template1")
            .with_extension("meta.json");
        fs::write(&meta_path, "not valid json {{{").unwrap();

        // Should return None instead of an error
        let result = store.load("http:test", "template1").unwrap();
        assert!(result.is_none());
    }

    #[test]
    fn write_content_is_atomic() {
        let temp = TempDir::new().unwrap();
        let store = CacheStore::new(temp.path());

        store.write_content("http:test", "tpl", "hello").unwrap();

        let path = store.content_path("http:test", "tpl");
        let content = fs::read_to_string(&path).unwrap();
        assert_eq!(content, "hello");
    }
}

