    Failed(String),
}

impl<'a> CacheRevalidator<'a> {
    /// Create a new revalidator.
    pub fn new(store: &'a CacheStore, git_clone_dir: impl Into<std::path::PathBuf>) -> Self {
        Self {
            store,
            http: HttpFetcher::new(),
            git: GitFetcher::new(git_clone_dir),
        }
    }

